import{az as o,P as a,Q as e,aQ as h}from"./chunks/framework.oHSDCGnP.js";import"./chunks/theme.SRuXo2Mz.js";const _=JSON.parse('{"title":"自定义 hook","description":"","frontmatter":{},"headers":[],"relativePath":"框架/vue/vue/自定义hook.md","filePath":"框架/vue/vue/自定义hook.md","lastUpdated":1785249401000}'),i={name:"框架/vue/vue/自定义hook.md"};function d(r,t,s,n,l,k){return a(),e("div",null,[...t[0]||(t[0]=[h('<h1 id="自定义-hook" tabindex="-1">自定义 hook <a class="header-anchor" href="#自定义-hook" aria-label="Permalink to “自定义 hook”">​</a></h1><h2 id="基本概念" tabindex="-1">基本概念 <a class="header-anchor" href="#基本概念" aria-label="Permalink to “基本概念”">​</a></h2><p>抽离可复用的功能，框架提供一些内置函数，在 hook 里可以调用，让这个功能拥有组件状态。</p><p>更加是弥补了 mixin、extend 的缺点：不清楚暴露出来的变量的作用、命名冲突、重用低效。mixin 属于隐式使用，hooks 更强调先声明后使用。</p><h2 id="为什么使用-hooks-hooks-如何诞生的" tabindex="-1">为什么使用 hooks，hooks 如何诞生的 <a class="header-anchor" href="#为什么使用-hooks-hooks-如何诞生的" aria-label="Permalink to “为什么使用 hooks，hooks 如何诞生的”">​</a></h2><p>hooks 代替了 mixin。</p><p>mixin 的不足：</p><ul><li><strong>不可知</strong>：在 mixin 中加入 props、data、methods 不向外抛出，属性同名则会导致命名冲突，导致不可知</li><li><strong>不易维护</strong>：没有抛出接收则不利于 mixin 维护</li></ul><h2 id="mixin-vs-hooks" tabindex="-1">mixin vs hooks <a class="header-anchor" href="#mixin-vs-hooks" aria-label="Permalink to “mixin vs hooks”">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>mixin</th><th>hooks</th></tr></thead><tbody><tr><td>使用方式</td><td>隐式混入</td><td>显式声明后使用</td></tr><tr><td>命名冲突</td><td>容易冲突</td><td>通过变量接收避免</td></tr><tr><td>来源清晰度</td><td>不清楚变量来源</td><td>清晰知道来源</td></tr><tr><td>复用效率</td><td>低</td><td>高</td></tr></tbody></table><h2 id="简单理解" tabindex="-1">简单理解 <a class="header-anchor" href="#简单理解" aria-label="Permalink to “简单理解”">​</a></h2><p>自定义 hook = 把可复用的状态和逻辑封装成函数，先声明后使用，告别 mixin 的隐式混入。</p>',12)])])}const c=o(i,[["render",d]]);export{_ as __pageData,c as default};
